  $hspjson${"slug": "healthcare-systems-and-policy", "title": "Healthcare Systems and Policy", "description": "This course examines healthcare as a system shaped by institutions, coverage, payment, delivery organizations, quality, law, politics, equity, public health, comparative systems, digital health, and policy analysis.", "topics": [{"id": "b25e951f-bfc0-47ed-a327-8073cfc23b5e", "type": "topic", "title": "Health Systems Foundations and Systems Thinking", "description": "Understand healthcare as a complex system shaped by institutions, incentives, professions, patients, communities, and policy choices.", "children": [{"id": "d58a0f17-0952-47a9-9a86-50312e405b9f", "type": "subtopic", "title": "Systems thinking in healthcare", "description": "Systems thinking helps students see why healthcare problems rarely have single causes or single fixes.", "children": [{"id": "61939b37-80d3-4cd3-9286-5b5768a241f6", "type": "concept", "title": "Complex adaptive systems"}, {"id": "6254d5c4-bf45-4cb6-819f-90afca1fbd3c", "type": "concept", "title": "Feedback loops"}, {"id": "ed678aa8-54a1-49b5-bbea-4fead405cafe", "type": "concept", "title": "Incentives"}, {"id": "2931bb63-fc5c-42ba-900a-92adacd0a5b9", "type": "concept", "title": "Unintended consequences"}]}, {"id": "8708510d-095a-4c6d-bced-c43f72fa7056", "type": "subtopic", "title": "Triple Aim, Quadruple Aim, and value", "description": "These frameworks organize system goals around outcomes, cost, experience, equity, and workforce sustainability.", "children": [{"id": "294461f2-4b74-4682-bae6-c0ac3ed42bbe", "type": "concept", "title": "Population health"}, {"id": "d8f1cc73-a8a1-4b56-af82-0a3460d8be7b", "type": "concept", "title": "Patient experience"}, {"id": "ff044e1a-a3ef-4af7-bbe8-3c9d7345e192", "type": "concept", "title": "Per capita cost"}, {"id": "7f9d2025-da04-432d-97e5-8d9e7532121b", "type": "concept", "title": "Workforce well-being and equity"}]}, {"id": "0787d135-3a69-42e6-8308-c9fdd30ed4ce", "type": "subtopic", "titl