ype": "concept", "title": "Long-term care"}, {"id": "965ad946-16be-444e-a928-f8db7c4b26b1", "type": "concept", "title": "Community health and public health agencies"}]}, {"id": "97033200-473b-44d2-9794-03fba6d393d1", "type": "subtopic", "title": "Governance and accountability", "description": "Healthcare accountability is distributed across regulators, payers, accreditors, purchasers, courts, and communities.", "children": [{"id": "f4c339ee-8c47-40c4-9318-7240377285f8", "type": "concept", "title": "Accreditation"}, {"id": "481a23a4-b574-4960-a005-3338c187a8ec", "type": "concept", "title": "Licensure"}, {"id": "d9ff8827-712f-42c5-add0-d26ec20e2f82", "type": "concept", "title": "Purchaser oversight"}, {"id": "deb0516b-5838-42ca-ab91-c1f5567c22f6", "type": "concept", "title": "Public reporting"}]}]}, {"id": "15ac0dc6-4747-4dbd-95b7-de6a497a5420", "type": "topic", "title": "Insurance Design, Coverage, Medicare, Medicaid, and the ACA", "description": "Explain how coverage works and how Medicare, Medicaid, Marketplace, employer-sponsored, and uninsured pathways affect access.", "children": [{"id": "17da8810-db02-4e6b-bd67-5fe0150893fb", "type": "subtopic", "title": "Coverage pathways", "description": "Coverage pathways determine what services people can access and how financially protected they are.", "children": [{"id": "ce7cd423-e9b5-4bb1-b3c1-c899ebf898a7", "type": "concept", "title": "Employer-sponsored insurance"}, {"id": "ec092ee9-8d28-4107-b07b-f45b16c83d47", "type": "concept", "title": "Marketplace coverage"}, {"id": "77c861e3-183e-4845-a469-a8be76cb7fdb", "type": "concept", "title": "Medicare"}, {"id": "bea82f79-db19-4a32-b292-e41d55e95499", "type": "concept", "title": "Medicaid and CHIP"}]}, {"id": "6a188da2-8536-432e-a1a7-3ad6e7dc2c6f", "type": "subtopic", "title": "Insurance design", "description": "Insurance design shapes behavior through premiums, deductibles, networks, formularies, and utilization management.", "children": [{"id": "db6f183f-5568-4f93-87d6-4054ab882ecf", "type": "concept", "title": "Premiums"}, {"id": "ac282312-a431-4b56-ac71-27a68c6fb901", "type": "concept", "title": "Deductibles and copays"}, {"id": "3d9f32c5-963d-4ee8-bf99-8ae5c12098c6", "type": "concept", "title": "Provider networks"}, {"id": "0e6e6b1d-f421-4415-95c1-2dac71f2f554", "type": "concept", "title": "Prior authorization"}]}, {"id": "86c491d2-c9fa-4a80-944c-a2845e905aac", "type": "subtopic", "title": "Coverage policy and reform", "description": "Coverage policy reveals the tradeoffs among universality, affordability, benefit design, public budgets, and political feasibility.", "children": [{"id": "9ccc227f-eb13-4d1f-982d-5f05f5f00db5", "type": "concept", "title": "Affordable Care Act"}, {"id": "4192df46-ea81-43a6-874e-b9ac847db4f3", "type": "concept", "title": "Medicaid expansion"}, {"id": "b987b26d-f91d-4c48-8afe-dde1acd73c64", "type": "concept", "title": "Uninsured and underinsured populations"}, {"id": "0a942d3c-5463-4d8e-b436-1d9c04831463", "type": "concept", "title": "Coverage churn"}]}]}, {"id": "222f4cc1-eef3-4d0c-aa2e-682c952c1fdd", "type": "topic", "title": "Provider Payment, Health Economics, Costs, and Affordability", "description": "Connect payment models, prices, spending, cost sharing, incentives, and affordability to system performance.", "children": [{"id": "30fab16d-021c-461f-aee1-fc41306b8615", "type": "subtopic", "title": "Payment models", "description": "Payment models create incentives that can support or undermine access, quality, coordination, and cost control.", "children": [{"id": "285190d9-b62d-4a5d-8ae5-82ff699788b4", "type": "concept", "title": "Fee-for-service"}, {"id": "7273b883-1481-4940-9ce8-92053cc263f4", "type": "concept", "title": "Capitation"}, {"id": "a57e0ae2-872d-458c-83b4-84fda6a07a84", "type": "concept", "title": "Bundled payments"}, {"id": "ab778642-d36f-4765-ad1a-e16042eb9580", "type": "concept", "title": "Global budgets"}]}, {"id": "5c412278-57bc-47c5-a094-534827cea535", "type": "subtopic", "title": "Health spending and prices", "description": "Students distinguish spending, price, utilization, administrative cost, and affordability.", "children": [{"id": "ccca72ea-e0ea-4e66-9d62-1485f825ada1", "type": "concept", "title": "National health expenditures"}, {"id": "f031a431-ef36-43dd-819c-ebd514b944c6", "type": "concept", "title": "Price variation"}, {"id": "a0fdbb7e-f861-4435-bbf3-79efc6a7252d", "type": "concept", "title": "Administrative complexity"}, {"id": "a72004c5-e8d3-4d3e-8172-11b257b78d56", "type": "concept", "title": "Prescription drug spending"}]}, {"id": "4fdbca67-949d-4062-893d-4e9085923af7", "type": "subtopic", "title": "Affordability and financial risk", "description": "Affordability connects policy design to real patient choices and delayed care.", "children": [{"id": "ace2175b-f7e8-43f3-9092-10c5cd80a10f", "type": "concept", "title": "Cost sharing"}, {"id": "5fd470e7-d975-4bdd-a9d3-e23a45aba100", "type": "concept", "title": "Medical debt"}, {"id": "6047765b-3c89-4be5-af65-3af3b0ed6601", "type": "concept", "title": "Underinsurance"}, {"id": "ca8caf13-70c0-438e-a5a0-72e288b271f8", "type": "concept", "title": "Out-of-pocket maximums"}]}]}, {"id": "451ba6eb-7c9f-4534-86af-c7616192c31e", "type": "topic", "title": "Private Insurance, Employer Coverage, and Market Dynamics", "description": "Analyze how private insurance markets, employer benefits, managed care, consolidation, and competition shape care delivery.", "children": [{"id": "88128a0d-0f7c-4515-8d6c-5fca40d634d0", "type": "subtopic", "title": "Employer-sponsored insurance", "description": "Employer coverage is central in the U.S. system and links health access to labor markets.", "children": [{"id": "7ff842fb-a4ec-4e74-b4ab-d329e98b02f4", "type": "concept", "title": "Benefit design"}, {"id": "d7e76b07-75f5-46ca-b087-1026cbb732b2", "type": "concept", "title": "Self-insured employers"}, {"id": "e3dfcbe5-6e43-40d8-8b4e-3e247207df05", "type": "concept", "title": "Risk pooling"}, {"id": "1807c874