, "type": "concept", "title": "Community hospitals"}, {"id": "24bc0e06-2f59-4b35-920d-4a59dbe5b52f", "type": "concept", "title": "Federally qualified health centers"}, {"id": "6b93bd56-001e-41aa-8310-f08720be59b8", "type": "concept", "title": "Integrated delivery systems"}]}, {"id": "56bb9b89-5dff-47d0-8ad5-e3e6f5bbb20a", "type": "subtopic", "title": "Health workforce composition", "description": "Workforce policy shapes who can provide care, where, under what scope, and at what cost.", "children": [{"id": "1bab399b-1039-4180-ab72-a1e0b24fdcce", "type": "concept", "title": "Physicians"}, {"id": "906ef1ce-d569-4318-a82b-54831b8b00fe", "type": "concept", "title": "Nurses and APRNs"}, {"id": "9db4aa42-63c6-4d87-a6d4-93770cfb2874", "type": "concept", "title": "PAs and allied health"}, {"id": "506ffab5-f5d9-4323-9afe-2e771da44aff", "type": "concept", "title": "Community health workers"}]}, {"id": "2e949bcc-3d7c-4cf4-a592-e557d265aca0", "type": "subtopic", "title": "Workforce shortages and distribution", "description": "Shortages are often about geography, specialty mix, burnout, training pipelines, and payment, not only headcount.", "children": [{"id": "22ca2388-861b-49e2-ab74-1dc408df63cf", "type": "concept", "title": "Rural access"}, {"id": "68d0f0ac-9a60-4aba-b320-badccf43293a", "type": "concept", "title": "Primary care gaps"}, {"id": "f22639ef-9195-4473-b968-a704673a9ea8", "type": "concept", "title": "Burnout"}, {"id": "6019ab48-e960-4316-81fb-7eff51bf283c", "type": "concept", "title": "Scope-of-practice debates"}]}]}, {"id": "f3f4c540-a173-4419-91b0-fd284e6a1a67", "type": "topic", "title": "Quality, Patient Safety, Measurement, and Value-Based Care", "description": "Use quality and safety frameworks to understand how systems measure performance and pursue better outcomes.", "children": [{"id": "9ac8fddc-3443-4727-aaf5-a31849b01f71", "type": "subtopic", "title": "Quality and safety foundations", "description": "Quality and safety translate system goals into measurable outcomes, safer processes, and learning from harm.", "children": [{"id": "65b8c46f-4f46-4c23-9a28-cf077cd36c5d", "type": "concept", "title": "Structure-process-outcome"}, {"id": "2601b690-81a7-465c-89de-181af917da8a", "type": "concept", "title": "Patient safety science"}, {"id": "3428adc6-f2f5-4b7b-8e24-11959b152b33", "type": "concept", "title": "High reliability"}, {"id": "9475f4a8-bcb7-4e3e-8405-7fa7985192af", "type": "concept", "title": "Equity-sensitive quality"}]}, {"id": "bc21840a-2d83-4c47-a3af-0b380cc0aaae", "type": "subtopic", "title": "Measurement and public reporting", "description": "Measures influence what systems prioritize, reward, and improve, but can also create measurement burden.", "children": [{"id": "f2a0ef91-9fb1-492f-9671-f83177a448d6", "type": "concept", "title": "Process measures"}, {"id": "37a8157c-3fcd-4497-b139-61b6ea69ddb9", "type": "concept", "title": "Outcome measures"}, {"id": "6f29a559-28b9-4c0d-9b72-feb7308daf1b", "type": "concept", "title": "Patient experience"}, {"id": "93935e3e-4a1f-4af0-b656-b272840666f1", "type": "concept", "title": "CMS quality programs"}]}, {"id": "6b8b5e79-aa1e-4121-9b26-c950eb395504", "type": "subtopic", "title": "Value-based care", "description": "Value-based care tries to shift payment toward outcomes, coordination, prevention, and population accountability.", "children": [{"id": "e43305d4-02bd-4d00-9252-9dd3bb86ed0f", "type": "concept", "title": "Accountable care organizations"}, {"id": "59b913bd-998c-406b-b093-238fada95fa5", "type": "concept", "title": "Hospital value-based purchasing"}, {"id": "7b797bcd-d65e-44a3-a51a-b36e38342676", "type": "concept", "title": "Readmission reduction"}, {"id": "4197f768-9e18-4cff-80c7-0dca94237594", "type": "concept", "title": "Risk adjustment"}]}]}, {"id": "f0f015cd-f8b2-4c31-9ec6-c12084d28200", "type": "topic", "title": "Healthcare Law, Regulation, Privacy, and Public Health Authority", "description": "Understand the legal and regulatory infrastructure that governs 