oncept", "title": "Civil liberties"}]}]}, {"id": "2a0302e8-d6d9-45cd-bf1f-b1b770dd904d", "type": "topic", "title": "Health Policy Process, Politics, Advocacy, and Stakeholders", "description": "Learn how health policy agendas are set, debated, enacted, implemented, opposed, and changed.", "children": [{"id": "12e0d828-ee1f-4ff8-9a4f-0fc355e88a99", "type": "subtopic", "title": "Policy process", "description": "The policy process gives students a realistic map from problem definition to implementation and evaluation.", "children": [{"id": "8e254610-f8ce-48a3-a6a5-7ba650e6420f", "type": "concept", "title": "Agenda setting"}, {"id": "7be1af55-681e-4f94-9a80-972734e627b1", "type": "concept", "title": "Policy formulation"}, {"id": "59a802a8-21e1-4772-bca9-8ada2472b31a", "type": "concept", "title": "Legislation and regulation"}, {"id": "fff93c3c-1a1c-41b4-85c6-e79e120eeeaa", "type": "concept", "title": "Implementation"}]}, {"id": "2756cab4-a68e-4c81-9537-66793f95f9ef", "type": "subtopic", "title": "Stakeholders and power", "description": "Policy outcomes depend on institutions, organized interests, public opinion, evidence, and political incentives.", "children": [{"id": "dd49f9e7-7474-4592-b294-6143c4397946", "type": "concept", "title": "Patients and communities"}, {"id": "7904ecf2-9072-4dfd-9659-37ce4eaccc0c", "type": "concept", "title": "Insurers and providers"}, {"id": "b070687d-5b04-45b5-b30a-b15f32204ab4", "type": "concept", "title": "Industry groups"}, {"id": "957868be-14df-4de5-97a1-57f0a3d62203", "type": "concept", "title": "Professional associations"}]}, {"id": "6cf660ad-4547-4f4d-85ce-39540bac0a56", "type": "subtopic", "title": "Advocacy strategies", "description": "Advocacy turns system knowledge into action while requiring credibility, coalition-building, and clear messaging.", "children": [{"id": "2e19f59a-458a-4a76-a9c2-288b88caae01", "type": "concept", "title": "Grassroots organizing"}, {"id": "a1514412-7e45-4c70-b826-bd4c93c304ad", "type": "concept", "titl