ention"}]}, {"id": "396b8894-b977-4af9-b183-e3af15a600ae", "type": "subtopic", "title": "Clinical-public health integration", "description": "Health systems increasingly connect clinical care to community and population-health goals.", "children": [{"id": "ad9512d7-eb62-4b5d-8890-8be8431d13dc", "type": "concept", "title": "Community benefit"}, {"id": "bc1dcf6e-8560-49a4-a2af-463b1250842d", "type": "concept", "title": "Population health management"}, {"id": "eb45b3ef-27d0-4548-8822-24736a40d4c7", "type": "concept", "title": "Referral to social services"}, {"id": "cfaa9f7c-52c8-4195-a94c-165fa3a9bb06", "type": "concept", "title": "Public health data sharing"}]}]}, {"id": "fcb454f9-df00-4378-b33e-704454fe85cc", "type": "topic", "title": "Comparative and Global Health Systems", "description": "Compare international systems to understand tradeoffs in financing, access, cost control, quality, and health outcomes.", "children": [{"id": "b6395f1a-0729-40cf-836a-c8d34fd3e983", "type": "subtopic", "title": "Comparative financing models", "description": "Comparisons help students see U.S. choices more clearly by contrasting other systems' coverage and payment structures.", "children": [{"id": "5ae0a5a9-3ebd-4d10-9d18-de81aa2cd785", "type": "concept", "title": "Single payer"}, {"id": "70e479bc-398a-49ff-b5fc-21bbc39d66ab", "type": "concept", "title": "Social insurance"}, {"id": "3e61bddf-0301-49f5-a32e-36a60c1aa81a", "type": "concept", "title": "National health service"}, {"id": "ab4c9df8-5b8a-4735-b140-35dfa1273582", "type": "concept", "title": "Multi-payer systems"}]}, {"id": "a7307ce6-4816-4cef-8e83-588216691429", "type": "subtopic", "title": "Performance comparison", "description": "International comparison highlights tradeoffs in cost, access, equity, wait times, outcomes, and administrative simplicity.", "children": [{"id": "f9ab0fb2-f2ed-4e5f-8d92-6b2da602a5e5", "type": "concept", "title": "Health expenditure"}, {"id": "2ea6a233-9d1f-4c55-bb4f-1dfd3e6c7b47", "type": "con