m definition"}, {"id": "a69eb744-26ad-4fcd-9c38-3ca2feda9387", "type": "concept", "title": "Policy alternatives"}, {"id": "cd533892-6a82-4424-b0a2-6799026874b7", "type": "concept", "title": "Criteria and tradeoffs"}, {"id": "b7073e43-5f95-4465-982f-64fdb8f09665", "type": "concept", "title": "Stakeholder analysis"}]}, {"id": "36259bd9-8da9-4b86-a14a-a7e12dc3d8ae", "type": "subtopic", "title": "Evaluation of reforms", "description": "Evaluation asks whether reforms changed coverage, access, cost, quality, equity, and unintended outcomes.", "children": [{"id": "079ec1e8-112b-47f9-957d-c130cba9d6bf", "type": "concept", "title": "Pre-post analysis"}, {"id": "e904321e-ade1-496d-8ee9-456fed0057a8", "type": "concept", "title": "Comparison groups"}, {"id": "59f3ba4e-8326-4879-abc7-0fa82c14aec9", "type": "concept", "title": "Implementation fidelity"}, {"id": "d8839657-8239-46b9-aa40-bbb5aafe5d7e", "type": "concept", "title": "Equity impact assessment"}]}, {"id": "68f6920d-f7a6-44fe-b048-4db28a20e92e", "type": "subtopic", "title": "Health policy memo", "description": "The memo is a practical capstone that trains students to write concise, evidence-based recommendations.", "children": [{"id": "d7ea02aa-8c85-49c6-b4d5-3ef82d7c6bf3", "type": "concept", "title": "Executive summary"}, {"id": "7724d062-c834-4f4c-a6ef-93cc5fe8ce03", "type": "concept", "title": "Evidence synthesis"}, {"id": "c4be1b2a-4d5d-4c3d-9adc-778c5b2c2bea", "type": "concept", "title": "Recommendation"}, {"id": "8b088dcd-7919-4705-9261-e71fef2bc735", "type": "concept", "title": "Implementation and risk considerations"}]}]}], "dbBacked": true}$hspjson$::jsonb,
