  data = $hspjson${"slug": "healthcare-systems-and-policy", "title": "Healthcare Systems and Policy", "description": "This course examines healthcare as a system shaped by institutions, coverage, payment, delivery organizations, quality, law, politics, equity, public health, comparative systems, digital health, and policy analysis.", "topics": [{"id": "b25e951f-bfc0-47ed-a327-8073cfc23b5e", "type": "topic", "title": "Health Systems Foundations and Systems Thinking", "description": "Understand healthcare as a complex system shaped by institutions, incentives, professions, patients, communities, and policy choices.", "children": [{"id": "d58a0f17-0952-47a9-9a86-50312e405b9f", "type": "subtopic", "title": "Systems thinking in healthcare", "description": "Systems thinking helps students see why healthcare problems rarely have single causes or single fixes.", "children": [{"id": "61939b37-80d3-4cd3-9286-5b5768a241f6", "type": "concept", "title": "Complex adaptive systems"}, {"id": "6254d5c4-bf45-4cb6-819f-90afca1fbd3c", "type": "concept", "title": "Feedback loops"}, {"id": "ed678aa8-54a1-49b5-bbea-4fead405cafe", "type": "concept", "title": "Incentives"}, {"id": "2931bb63-fc5c-42ba-900a-92adacd0a5b9", "type": "concept", "title": "Unintended consequences"}]}, {"id": "8708510d-095a-4c6d-bced-c43f72fa7056", "type": "subtopic", "title": "Triple Aim, Quadruple Aim, and value", "description": "These frameworks organize system goals around outcomes, cost, experience, equity, and workforce sustainability.", "children": [{"id": "294461f2-4b74-4682-bae6-c0ac3ed42bbe", "type": "concept", "title": "Population health"}, {"id": "d8f1cc73-a8a1-4b56-af82-0a3460d8be7b", "type": "concept", "title": "Patient experience"}, {"id": "ff044e1a-a3ef-4af7-bbe8-3c9d7345e192", "type": "concept", "title": "Per capita cost"}, {"id": "7f9d2025-da04-432d-97e5-8d9e7532121b", "type": "concept", "title": "Workforce well-being and equity"}]}, {"id": "0787d135-3a69-42e6-8308-c9fdd30ed4ce", "type": "subtopic", "title": "Health systems science", "description": "Health systems science gives future health professionals a shared language for delivery, policy, quality, teamwork, and improvement.", "children": [{"id": "77baad52-c713-4302-9399-814802c4acf3", "type": "concept", "title": "Systems roles"}, {"id": "84bec8e9-eab0-4825-bc28-696f9674a8bc", "type": "concept", "title": "Interprofessional teams"}, {"id": "b07e4bfb-04d3-4f13-bf2d-8e8c41921b42", "type": "concept", "title": "Care coordination"}, {"id": "547fa28b-260d-49fc-aaad-c0d21f809200", "type": "concept", "title": "Policy and practice links"}]}]}, {"id": "accea652-ea2a-4b6f-8205-789176ad3b91", "type": "topic", "title": "Structure of the U.S. Healthcare System", "description": "Map the major public, private, nonprofit, and community-based actors that organize, finance, deliver, and regulate care.", "children": [{"id": "cdd6378c-3639-4cc6-baf3-e8f8e6443e9b", "type": "subtopic", "title": "Major system actors", "description": "Students learn who does what in a system with public and private authority split across many organizations.", "children": [{"id": "7362fd3e-a1d5-4797-9823-0b78a91a97f6", "type": "concept", "title": "Federal agencies"}, {"id": "5414cc48-aa05-46f7-a042-df96977e0bd4", "type": "concept", "title": "State governments"}, {"id": "8bdff4af-ee6f-448e-96f8-e3bbbcc76361", "type": "concept", "title": "Private insurers"}, {"id": "98e818de-b4c3-4b7b-9527-d74bebd804dc", "type": "concept", "title": "Providers and professional organizations"}]}, {"id": "3d34587c-7837-4295-a322-805b537b70f8", "type": "subtopic", "title": "Care delivery settings", "description": "Delivery settings show how care is fragmented across acute, outpatient, post-acute, community, and public health spaces.", "children": [{"id": "c2d80271-d83c-4893-ad69-4be8448140cd", "type": "concept", "title": "Hospitals"}, {"id": "25e5223f-761a-4b8f-be26-27ad4ca3c768", "type": "concept", "title": "Ambulatory care"}, {"id": "730e741b-cc37-4bd1-adb5-03c2a33faf64", "type": "concept", "title": "Long-term care"}, {"id": "965ad946-16be-444e-a928-f8db7c4b26b1", "type": "concept", "title": "Community health and public health agencies"}]}, {"id": "97033200-473b-44d2-9794-03fba6d393d1", "type": "subtopic", "title": "Governance and accountability", "description": "Healthcare accountability is distributed across regulators, payers, accreditors, purchasers, courts, and communities.", "children": [{"id": "f4c339ee-8c47-40c4-9318-7240377285f8", "type": "concept", "title": "Accreditation"}, {"id": "481a23a4-b574-4960-a005-3338c187a8ec", "type": "concept", "title": "Licensure"}, {"id": "d9ff8827-712f-42c5-add0-d26ec20e2f82", "type": "concept", "title": "Purchaser oversight"}, {"id": "deb0516b-5838-42ca-ab91-c1f5567c22f6", "type": "concept", "title": "Public reporting"}]}]}, {"id": "15ac0dc6-4747-4dbd-95b7-de6a497a5420", "type": "topic", "title": "Insurance Design, Coverage, Medicare, Medicaid, and the ACA", "description": "Explain how coverage works and how Medicare, Medicaid, Marketplace, employer-sponsored, and uninsured pathways affect access.", "children": [{"id": "17da8810-db02-4e6b-bd67-5fe0150893fb", "type": "subtopic", "title": "Coverage pathways", "description": "Coverage pathways determine what services people can access and how financially protected they are.", "children": [{"id": "ce7cd423-e9b5-4bb1-b3c1-c899ebf898a7", "type": "concept", "title": "Employer-sponsored insurance"}, {"id": "ec092ee9-8d28-4107-b07b-f45b16c83d47", "type": "concept", "title": "Marketplace coverage"}, {"id": "77c861e3-183e-4845-a469-a8be76cb7fdb", "type": "concept", "title": "Medicare"}, {"id": "bea82f79-db19-4a32-b292-e41d55e95499", "type": "concept", "title": "Medicaid and CHIP"}]}, {"id": "6a188da2-8536-432e-a1a7-3ad6e7dc2c6f", "type": "subtopic", "title": "Insurance design", "description": "Insurance design shapes behavior through premiums, deductibles, networks, formularies, and utilization management.", "children": [{"id": "db6f183f-5568-4f93-87d6-4054ab882ecf", "type": "concept", "title": "Premiums"}, {"id": "ac282312-a431-4b56-ac71-27a68c6fb901", "type": "concept", "title": "Deductibles and copays"}, {"id": "3d9f32c5-963d-4ee8-bf99-8ae5c12098c6", "type": "concept", "title": "Provider networks"}, {"id": "0e6e6b1d-f421-4415-95c1-2dac71f2f554", "type": "concept", "title": "Prior authorization"}]}, {"id": "86c491d2-c9fa-4a80-944c-a2845e905aac", "type": "subtopic", "title": "Coverage policy and reform", "description": "Coverage policy reveals the tradeoffs among universality, affordability, benefit design, public budgets, and political feasibility.", "children": [{"id": "9ccc227f-eb13-4d1f-982d-5f05f5f00db5", "type": "concept", "title": "Affordable Care Act"}, {"id": "4192df46-ea81-43a6-874e-b9ac847db4f3", "type": "concept", "title": "Medicaid expansion"}, {"id": "b987b26d-f91d-4c48-8afe-dde1acd73c64", "type": "concept", "title": "Uninsured and underinsured populations"}, {"id": "0a942d3c-5463-4d8e-b436-1d9c04831463", "type": "concept", "title": "Coverage churn"}]}]}, {"id": "222f4cc1-eef3-4d0c-aa2e-682c952c1fdd", "type": "topic", "title": "Provider Payment, Health Economics, Costs, and Affordability", "description": "Connect payment models, prices, spending, cost sharing, incentives, and affordability to system performance.", "children": [{"id": "30fab16d-021c-461f-aee1-fc41306b8615", "type": "subtopic", "title": "Payment models", "description": "Payment models create incentives that can support or undermine access, quality, coordination, and cost control.", "children": [{"id": "285190d9-b62d-4a5d-8ae5-82ff699788b4", "type": "concept", "title": "Fee-for-service"}, {"id": "7273b883-1481-4940-9ce8-92053cc263f4", "type": "concept", "title": "Capitation"}, {"id": "a57e0ae2-872d-458c-83b4-84fda6a07a84", "type": "concept", "title": "Bundled payments"}, {"id": "ab778642-d36f-4765-ad1a-e16042eb9580", "type": "concept", "title": "Global budgets"}]}, {"id": "5c412278-57bc-47c5-a094-534827cea535", "type": "subtopic", "title": "Health spending and prices", "description": "Students distinguish spending, price, utilization, administrative cost, and affordability.", "children": [{"id": "ccca72ea-e0ea-4e66-9d62-1485f825ada1", "type": "concept", "title": "National health expenditures"}, {"id": "f031a431-ef36-43dd-819c-ebd514b944c6", "type": "concept", "title": "Price variation"}, {"id": "a0fdbb7e-f861-4435-bbf3-79efc6a7252d", "type": "concept", "title": "Administrative complexity"}, {"id": "a72004c5-e8d3-4d3e-8172-11b257b78d56", "type": "concept", "title": "Prescription drug spending"}]}, {"id": "4fdbca67-949d-4062-893d-4e9085923af7", "type": "subtopic", "title": "Affordability and financial risk", "description": "Affordability connects policy design to real patient choices and delayed care.", "children": [{"id": "ace2175b-f7e8-43f3-9092-10c5cd80a10f", "type": "concept", "title": "Cost sharing"}, {"id": "5fd470e7-d975-4bdd-a9d3-e23a45aba100", "type": "concept", "title": "Medical debt"}, {"id": "6047765b-3c89-4be5-af65-3af3b0ed6601", "type": "concept", "title": "Underinsurance"}, {"id": "ca8caf13-70c0-438e-a5a0-72e288b271f8", "type": "concept", "title": "Out-of-pocket maximums"}]}]}, {"id": "451ba6eb-7c9f-4534-86af-c7616192c31e", "type": "topic", "title": "Private Insurance, Employer Coverage, and Market Dynamics", "description": "Analyze how private insurance markets, employer benefits, managed care, consolidation, and competition shape care delivery.", "children": [{"id": "88128a0d-0f7c-4515-8d6c-5fca40d634d0", "type": "subtopic", "title": "Employer-sponsored insurance", "description": "Employer coverage is central in the U.S. system and links health access to labor markets.", "children": [{"id": "7ff842fb-a4ec-4e74-b4ab-d329e98b02f4", "type": "concept", "title": "Benefit design"}, {"id": "d7e76b07-75f5-46ca-b087-1026cbb732b2", "type": "concept", "title": "Self-insured employers"}, {"id": "e3dfcbe5-6e43-40d8-8b4e-3e247207df05", "type": "concept", "title": "Risk pooling"}, {"id": "1807c874-6eee-4998-b58b-0f8ac01e1aa8", "type": "concept", "title": "Job lock"}]}, {"id": "acd0855e-7439-479b-a310-7b00ed86801e", "type": "subtopic", "title": "Managed care and networks", "description": "Managed care tools aim to control cost and quality but can also create access barriers.", "children": [{"id": "0c1a819e-ff32-4391-81de-af7c10e27eaa", "type": "concept", "title": "HMOs and PPOs"}, {"id": "c901e3b4-d9f6-4786-9cce-c1e172cabe39", "type": "concept", "title": "Narrow networks"}, {"id": "792c30d1-8208-4462-942b-71f799b07813", "type": "concept", "title": "Utilization review"}, {"id": "5c559a9a-012c-410d-9b15-e56bf8702e6e", "type": "concept", "title": "Care management"}]}, {"id": "a196c984-524f-478e-825c-ff6c82a69354", "type": "subtopic", "title": "Market power and consolidation", "description": "Market structure affects prices, bargaining power, availability of services, and local access.", "children": [{"id": "0ffe9d7a-27f4-46c2-87fe-ecafb5d2ef6f", "type": "concept", "title": "Hospital consolidation"}, {"id": "a53c3435-659f-4eb0-ab03-4716acf8f4c6", "type": "concept", "title": "Insurer consolidation"}, {"id": "a3ef897d-b3fd-4d90-a1de-622a440946ab", "type": "concept", "title": "Vertical integration"}, {"id": "822da3be-c2f3-4720-bf7d-2398466fad25", "type": "concept", "title": "Antitrust concerns"}]}]}, {"id": "57c3efaf-f127-470a-9356-2e6f6862d4bc", "type": "topic", "title": "Healthcare Delivery Organizations and Workforce Policy", "description": "Study hospitals, clinics, public health agencies, long-term care, health professionals, scope of practice, staffing, and workforce shortages.", "children": [{"id": "575f3829-89ea-4a22-831f-33a86345478d", "type": "subtopic", "title": "Delivery organizations", "description": "Students compare the missions, incentives, and constraints of different care organizations.", "children": [{"id": "a69a2951-425e-484d-8027-d674ef8147c7", "type": "concept", "title": "Academic medical centers"}, {"id": "a3bf271b-a7bd-45f3-a8e4-4b801584e57e", "type": "concept", "title": "Community hospitals"}, {"id": "24bc0e06-2f59-4b35-920d-4a59dbe5b52f", "type": "concept", "title": "Federally qualified health centers"}, {"id": "6b93bd56-001e-41aa-8310-f08720be59b8", "type": "concept", "title": "Integrated delivery systems"}]}, {"id": "56bb9b89-5dff-47d0-8ad5-e3e6f5bbb20a", "type": "subtopic", "title": "Health workforce composition", "description": "Workforce policy shapes who can provide care, where, under what scope, and at what cost.", "children": [{"id": "1bab399b-1039-4180-ab72-a1e0b24fdcce", "type": "concept", "title": "Physicians"}, {"id": "906ef1ce-d569-4318-a82b-54831b8b00fe", "type": "concept", "title": "Nurses and APRNs"}, {"id": "9db4aa42-63c6-4d87-a6d4-93770cfb2874", "type": "concept", "title": "PAs and allied health"}, {"id": "506ffab5-f5d9-4323-9afe-2e771da44aff", "type": "concept", "title": "Community health workers"}]}, {"id": "2e949bcc-3d7c-4cf4-a592-e557d265aca0", "type": "subtopic", "title": "Workforce shortages and distribution", "description": "Shortages are often about geography, specialty mix, burnout, training pipelines, and payment, not only headcount.", "children": [{"id": "22ca2388-861b-49e2-ab74-1dc408df63cf", "type": "concept", "title": "Rural access"}, {"id": "68d0f0ac-9a60-4aba-b320-badccf43293a", "type": "concept", "title": "Primary care gaps"}, {"id": "f22639ef-9195-4473-b968-a704673a9ea8", "type": "concept", "title": "Burnout"}, {"id": "6019ab48-e960-4316-81fb-7eff51bf283c", "type": "concept", "title": "Scope-of-practice debates"}]}]}, {"id": "f3f4c540-a173-4419-91b0-fd284e6a1a67", "type": "topic", "title": "Quality, Patient Safety, Measurement, and Value-Based Care", "description": "Use quality and safety frameworks to understand how systems measure performance and pursue better outcomes.", "children": [{"id": "9ac8fddc-3443-4727-aaf5-a31849b01f71", "type": "subtopic", "title": "Quality and safety foundations", "description": "Quality and safety translate system goals into measurable outcomes, safer processes, and learning from harm.", "children": [{"id": "65b8c46f-4f46-4c23-9a28-cf077cd36c5d", "type": "concept", "title": "Structure-process-outcome"}, {"id": "2601b690-81a7-465c-89de-181af917da8a", "type": "concept", "title": "Patient safety science"}, {"id": "3428adc6-f2f5-4b7b-8e24-11959b152b33", "type": "concept", "title": "High reliability"}, {"id": "9475f4a8-bcb7-4e3e-8405-7fa7985192af", "type": "concept", "title": "Equity-sensitive quality"}]}, {"id": "bc21840a-2d83-4c47-a3af-0b380cc0aaae", "type": "subtopic", "title": "Measurement and public reporting", "description": "Measures influence what systems prioritize, reward, and improve, but can also create measurement burden.", "children": [{"id": "f2a0ef91-9fb1-492f-9671-f83177a448d6", "type": "concept", "title": "Process measures"}, {"id": "37a8157c-3fcd-4497-b139-61b6ea69ddb9", "type": "concept", "title": "Outcome measures"}, {"id": "6f29a559-28b9-4c0d-9b72-feb7308daf1b", "type": "concept", "title": "Patient experience"}, {"id": "93935e3e-4a1f-4af0-b656-b272840666f1", "type": "concept", "title": "CMS quality programs"}]}, {"id": "6b8b5e79-aa1e-4121-9b26-c950eb395504", "type": "subtopic", "title": "Value-based care", "description": "Value-based care tries to shift payment toward outcomes, coordination, prevention, and population accountability.", "children": [{"id": "e43305d4-02bd-4d00-9252-9dd3bb86ed0f", "type": "concept", "title": "Accountable care organizations"}, {"id": "59b913bd-998c-406b-b093-238fada95fa5", "type": "concept", "title": "Hospital value-based purchasing"}, {"id": "7b797bcd-d65e-44a3-a51a-b36e38342676", "type": "concept", "title": "Readmission reduction"}, {"id": "4197f768-9e18-4cff-80c7-0dca94237594", "type": "concept", "title": "Risk adjustment"}]}]}, {"id": "f0f015cd-f8b2-4c31-9ec6-c12084d28200", "type": "topic", "title": "Healthcare Law, Regulation, Privacy, and Public Health Authority", "description": "Understand the legal and regulatory infrastructure that governs access, privacy, emergency care, insurance, and public health powers.", "children": [{"id": "78a06f0b-3ef1-41fe-b4f5-18cbf541b524", "type": "subtopic", "title": "Health law and regulation", "description": "Law defines the boundaries of coverage, delivery, professional practice, and organizational responsibility.", "children": [{"id": "cd8221cf-9fd3-4ee2-b516-45a736c42757", "type": "concept", "title": "HIPAA"}, {"id": "4bd1c6fd-2a78-46ca-bdff-1447a9f68284", "type": "concept", "title": "EMTALA"}, {"id": "5303bbc2-15c2-43df-84f6-7e09c75dafa7", "type": "concept", "title": "Insurance regulation"}, {"id": "567f906b-ec63-41fc-9e5c-d28556e21e23", "type": "concept", "title": "Antitrust and fraud-and-abuse basics"}]}, {"id": "bced8714-f7d9-4157-888f-c6e2c44fe495", "type": "subtopic", "title": "Federal, state, and local roles", "description": "Students learn why healthcare authority is distributed and why policy implementation varies by state and locality.", "children": [{"id": "f0292cf6-8f53-40e1-a5bf-a9ca57ffd5a4", "type": "concept", "title": "Federal payment rules"}, {"id": "4802dec0-207e-4a71-b27d-708599a5405c", "type": "concept", "title": "State Medicaid programs"}, {"id": "35cd7676-e9b6-47e2-a929-9b3dcd7b8b9f", "type": "concept", "title": "Local public health authority"}, {"id": "15134a85-cbfc-4a22-be8b-d7bbd881738e", "type": "concept", "title": "Courts and administrative agencies"}]}, {"id": "c70f56f7-0a87-4703-8429-2e62096fb19b", "type": "subtopic", "title": "Ethics and public health authority", "description": "Policy decisions require balancing autonomy, collective risk, equity, evidence, and legal power.", "children": [{"id": "7fefc140-0228-44cd-ab94-6ad637676aa3", "type": "concept", "title": "Public health mandates"}, {"id": "06f0bc86-8d94-4989-b734-356ecfda665c", "type": "concept", "title": "Emergency powers"}, {"id": "aed313f9-0328-4962-87b7-e109752e1c2f", "type": "concept", "title": "Resource allocation"}, {"id": "b60f560b-7b9b-4a22-9d09-53db6a81f832", "ty